// Course-completion approval, immutable decisions, and certificates.
func (q *Queries) ListCompletionCandidates(ctx context.Context, arg ListCompletionCandidatesParams) ([]ListCompletionCandidatesRow, error) {
	rows, err := q.db.Query(ctx, listCompletionCandidates,
		arg.Search,
		arg.CourseID,
		arg.ClassID,
		arg.Eligibility,
		arg.SortBy,
		arg.SortOrder,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCompletionCandidatesRow{}
	for rows.Next() {
		var i ListCompletionCandidatesRow
		if err := rows.Scan(
			&i.ClassID,
			&i.ClassCode,
			&i.ClassName,
			&i.ClassStatus,
			&i.StudentID,
			&i.StudentCode,
			&i.StudentName,
			&i.StudentUserID,
			&i.CourseID,
			&i.CourseCode,
			&i.CourseName,
			&i.TotalSessions,
			&i.MinimumAttendancePct,
			&i.CompletedSessions,
			&i.AttendanceRecords,
			&i.AttendedSessions,
			&i.ExcusedSessions,
			&i.RequiredCompetenciesTotal,
			&i.RequiredCompetenciesMet,
			&i.RequiredTestsTotal,
			&i.RequiredTestsPassed,
			&i.FinalExamScore,
			&i.FinalExamCount,
			&i.RequiredAssessments,
			&i.CompletedAssessments,
			&i.CompletionID,
			&i.PersistedStatus,
			&i.ReviewedBy,
			&i.ReviewedAt,
			&i.ReviewNote,
			&i.CurrentCertificateID,
			&i.CurrentCertificateNumber,
			&i.AttendancePct,
			&i.IsEligible,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

